function scheduleError(assignment){if(!Array.isArray(assignment)||assignment.length!==3||assignment.some(n=>!Number.isInteger(n)||n<0||n>2))return 'Choose one worker for every job. Nothing was signed.';const names=['Moss','Pip','Bolt'],duplicates=[...new Set(assignment.filter((n,i)=>assignment.indexOf(n)!==i))],cost=assignment.reduce((sum,n,i)=>sum+JOB_COSTS[i][n],0);return 'That schedule does not fit. '+(duplicates.length?duplicates.map(n=>names[n]).join(' and ')+' is assigned more than once. ':'')+(cost>6?`Total cost ${cost} exceeds 6. `:'')+'Use each worker once and keep the total cost at six or below. Nothing was signed; no fee was paid.';}
function scheduleSummary(state){return ['Water','Delivery','Power'].map((job,i)=>job+': '+['Moss','Pip','Bolt'][[state.a,state.b,state.c][i]]).join(' · ');}
