const recover=(sdk,templates,journal,owners)=>(journal.kind==='composed'?derivePublicV4ComposedRecoveryPlan:derivePublicV4RecoveryPlan)(sdk,{templates,journal,keysPublic:owners});
export function validatePublicV4State(sdk,templates,value,owners){if(value===undefined)return empty();if(!value||value.version!==1||Object.keys(value).some(k=>!['version','activity'].includes(k))||!Array.isArray(value.activity)||value.activity.length>160)throw Error('Invalid world recovery');const ids=new Set();for(const r of value.activity){if(ids.has(r.journal?.id))throw Error('Duplicate world transaction record');ids.add(r.journal?.id);if(!r||Object.keys(r).some(k=>!['journal','checkpoint','attempted','submitted','observed','applied','outputsObserved','acceptingBlock','scanCursor','scanCaughtUp'].includes(k))||!hex(r.checkpoint))throw Error('Invalid world transaction record');recover(sdk,templates,r.journal,owners);r.observed=false;r.applied=false;r.outputsObserved=false;r.acceptingBlock=null;r.scanCursor=null;r.scanCaughtUp=false;}return value;}
export function derivePublicV4Cells(sdk,templates,activity,owners,kind){const c={sdk,templates,owners};if(!c.sdk)return [];const map=new Map(),spent=new Set();for(const record of activity.filter(r=>r.applied)){const p=recover(c.sdk,c.templates,record.journal,c.owners);for(const i of p.transaction.inputs)spent.add(`${i.previousOutpoint.transactionId}:${i.previousOutpoint.index}`);const states=p.genesis||p.states;states.forEach((s,i)=>{const type=p.kind==='composed'?(i<3?'bundle':'agent'):p.kind,index=p.kind==='composed'&&i===3?4:i;if(type!==kind)return;const asset=instantiateV4(c.sdk,c.templates[type],type,s),o=p.transaction.outputs[index];map.set(`${p.transaction.id}:${index}`,{asset,transactionId:p.transaction.id,index,amount:o.value,covenantId:o.covenant.covenantId.toString()});});}return [...map.entries()].filter(([id])=>!spent.has(id)).map(([,cell])=>cell);}
