 const controls=document.createElement('div');controls.className='v4-testnet-controls';controls.innerHTML='<button data-v4-wallet-menu aria-label="Your test wallet">Wallet</button><button data-v4-activity-menu>Activity</button><h3>Make the rule real on Testnet-10</h3><p data-v4-action-help></p><button class="primary" data-v4-send>Start this contract</button><button data-v4-revoke hidden>Return robot budget</button><button data-v4-observe>Check saved transactions</button><button data-v4-retry hidden>Retry identical saved transaction</button><p data-v4-node-status role="status" aria-live="polite"></p><div data-v4-transaction></div><div class="v4-dag" data-v4-dag></div>';game.mountControls(controls);const services=createV4LegacyServices({root:host.root,selectService:host.openService,isPending:()=>host.pending()||pending(),onChange:view=>{serviceView=view;if(view){selected=view.kind;game.select(selected);}render();},onError:error=>{status=error.message;render();}});const dagView=mountV4Dag(q('dag'));dagView.update({status:'illustrative',inputs:[],outputs:[]});
