 function select(kind,fromGame=false){if(guide&&(fromGame||kind!==story[guide.index].kind)){const step=story[guide.index];selected=step.kind;game.select(selected);if(kind!==selected)guideFeedback='The guided tour is still in progress. '+(guide.result?'Choose Continue for the next step.':'First: '+step.button+'.')+' Choose Explore freely to leave the tour.';render();return;}if(fromGame){townFinish=false;argentOpen=false;bridgeTour=null;}if(fromGame&&working){game.select(selected);return;}selected=kind;if(!fromGame)game.select(kind);document.querySelectorAll('[data-public-v4-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.publicV4Kind===kind)));render();}
