 async function check(){if(!records().length)return;await host.nodeInfo();const c=ctx();for(const r of records()){if(r.acceptingBlock&&r.applied)continue;const p=recover(c.sdk,c.templates,r.journal,c.owners),outputs=p.transaction.outputs.map((o,index)=>({index,o,address:c.sdk.addressFromScriptPublicKey(o.scriptPublicKey,'testnet-10').toString()}));const {entries}=await c.call(c.rpc.getUtxosByAddresses([...new Set(outputs.map(x=>x.address))]));r.outputsObserved=outputs.every(({index,o})=>entries.some(e=>e.outpoint.transactionId===r.journal.id&&e.outpoint.index===index&&e.amount===o.value&&e.entry.scriptPublicKey.script===o.scriptPublicKey.script&&e.entry.scriptPublicKey.version===o.scriptPublicKey.version&&(e.entry.covenantId?.toString()||null)===(o.covenant?.covenantId?.toString()||null)));Object.assign(r,await observePublicAcceptance(c.rpc,{...r,id:r.journal.id},{call:c.call}));r.observed=Boolean(r.acceptingBlock)||r.outputsObserved;r.applied=r.observed;lastPlan=p;if(r.acceptingBlock){game.transaction({id:r.journal.id,status:'accepted',kind:({bundle:'market',launch:'coordination',compute:'computation',composed:'market'}[p.kind]||p.kind),acceptingBlock:r.acceptingBlock,...animationInfo(p)});if(guide?.awaitingId===r.journal.id){guide.result=true;guideResult=resultText(p);}const kind=p.kind==='composed'?'bundle':p.kind,change=p.kind==='composed'?{settled:true}:kind==='launch'?{launched:p.operation===1,readyMembers:derivePublicV4Cells(c.sdk,c.templates,records().filter(record=>record.acceptingBlock),c.owners,'launch').filter(cell=>cell.asset.state.ready).map(cell=>cell.asset.state.member)}:kind==='compute'?{verified:p.operation===0,paid:p.operation===0}:kind==='agent'?{budget:Number(p.transaction.outputs.find(o=>o.covenant)?.value||0n)}:p.states[0]||{};game.observed(kind,change,{transactionId:r.journal.id,acceptingBlock:r.acceptingBlock});}}
 await host.saveState(state());const r=records().at(-1);status=r.acceptingBlock?resultText(lastPlan):r.outputsObserved?'The node shows the new outputs; final acceptance is still being checked. Open Activity to check the saved transaction.':'The node has not confirmed this saved transaction yet. Open Activity and choose Check saved transactions. Another click will not send new funds.';if(guide&&!guide.result)guideFeedback=status;render();await host.refresh();if(lastPlan){q('transaction').innerHTML=renderV4Transaction({inputs:lastPlan.transaction.inputs.map((i,n)=>({label:'Input '+n,amount:String(i.utxo.amount),state:lastPlan.tokens[n]?.state||'Wallet coins'})),outputs:lastPlan.transaction.outputs.map((o,n)=>({label:'Output '+n,amount:String(o.value),state:o.covenant?'Covenant successor':'Payment or change'})),rules:[{label:'Exact outputs observed',valid:r.outputsObserved},{label:'Accepted-chain observation',valid:Boolean(r.acceptingBlock)}],fee:lastPlan.fee,status});game.setEvidence(q('transaction').innerHTML);}if(r.acceptingBlock)await drawDag(r);}
